import { describe, expect, it } from 'vitest';
import {
  CURRENT_VERSION,
  DEFAULT_CONTENT_LAYERS,
  DEFAULT_EXPORT_LABELS,
  DOCUMENT_TOKENS_EXPORT_LABELS,
  SCHEMA_VERSION_HISTORY,
  type CodeItem,
  type DoclingDocument,
  type FieldHeadingItem,
  type FieldItem,
  type FieldRegionItem,
  type FieldValueItem,
  type FormItem,
  type FormulaItem,
  type InlineGroup,
  type KeyValueItem,
  type ListGroup,
  type ListItem,
  type NodeItem,
  type OrderedList,
  type PictureBarChartData,
  type PictureClassificationData,
  type PictureDescriptionData,
  type PictureItem,
  type PictureLineChartData,
  type PictureMiscData,
  type PictureMoleculeData,
  type PicturePieChartData,
  type PictureScatterChartData,
  type PictureStackedBarChartData,
  type PictureTabularChartData,
  type SectionHeaderItem,
  type TableItem,
  type TextItem,
  type TitleItem,
  isDocling,
  isDoclingAnnotation,
  isDoclingDocItem,
} from '../src/types';

describe('Constants', () => {
  it('exports CURRENT_VERSION as 1.10.0', () => {
    expect(CURRENT_VERSION).toBe('1.10.0');
  });

  it('exports DEFAULT_CONTENT_LAYERS with body', () => {
    expect(DEFAULT_CONTENT_LAYERS).toEqual(['body']);
  });

  it('exports DEFAULT_EXPORT_LABELS with 25 labels', () => {
    expect(DEFAULT_EXPORT_LABELS).toContain('title');
    expect(DEFAULT_EXPORT_LABELS).toContain('marker');
    expect(DEFAULT_EXPORT_LABELS).toContain('field_key');
    expect(DEFAULT_EXPORT_LABELS).toContain('handwritten_text');
    expect(DEFAULT_EXPORT_LABELS.length).toBe(25);
  });

  it('exports field_region and field_item in DEFAULT_EXPORT_LABELS', () => {
    expect(DEFAULT_EXPORT_LABELS).toContain('field_region');
    expect(DEFAULT_EXPORT_LABELS).toContain('field_item');
  });

  it('inherits field_region and field_item in DOCUMENT_TOKENS_EXPORT_LABELS', () => {
    expect(DOCUMENT_TOKENS_EXPORT_LABELS).toContain('field_region');
    expect(DOCUMENT_TOKENS_EXPORT_LABELS).toContain('field_item');
  });

  it('exports DOCUMENT_TOKENS_EXPORT_LABELS containing footnote, caption, key_value_region, form', () => {
    expect(DOCUMENT_TOKENS_EXPORT_LABELS).toContain('footnote');
    expect(DOCUMENT_TOKENS_EXPORT_LABELS).toContain('caption');
    expect(DOCUMENT_TOKENS_EXPORT_LABELS).toContain('key_value_region');
    expect(DOCUMENT_TOKENS_EXPORT_LABELS).toContain('form');
  });

  it('DOCUMENT_TOKENS_EXPORT_LABELS has no duplicate entries', () => {
    const unique = new Set(DOCUMENT_TOKENS_EXPORT_LABELS);
    expect(unique.size).toBe(DOCUMENT_TOKENS_EXPORT_LABELS.length);
  });

  it('exports SCHEMA_VERSION_HISTORY as a non-empty array', () => {
    expect(Array.isArray(SCHEMA_VERSION_HISTORY)).toBe(true);
    expect(SCHEMA_VERSION_HISTORY.length).toBeGreaterThan(0);
  });

  it('SCHEMA_VERSION_HISTORY entries have schema, library_version, note fields', () => {
    for (const entry of SCHEMA_VERSION_HISTORY) {
      expect(typeof entry.schema).toBe('string');
      expect(typeof entry.library_version).toBe('string');
      expect(typeof entry.note).toBe('string');
    }
  });

  it('SCHEMA_VERSION_HISTORY last entry matches CURRENT_VERSION', () => {
    const last = SCHEMA_VERSION_HISTORY[SCHEMA_VERSION_HISTORY.length - 1];
    expect(last.schema).toBe(CURRENT_VERSION);
  });
});

// ---------------------------------------------------------------------------
// isDocling — NodeItem / GroupItem / DocItem
// ---------------------------------------------------------------------------

describe('isDocling.NodeItem', () => {
  it('accepts any object with self_ref', () => {
    expect(isDocling.NodeItem({ self_ref: '#/body' })).toBe(true);
  });

  it('rejects objects without self_ref', () => {
    expect(isDocling.NodeItem({ label: 'text' })).toBe(false);
    expect(isDocling.NodeItem({})).toBe(false);
  });
});

describe('isDocling.GroupItem', () => {
  it('identifies body by self_ref', () => {
    const body: NodeItem = { self_ref: '#/body' };
    expect(isDocling.GroupItem(body)).toBe(true);
  });

  it('identifies furniture by self_ref', () => {
    const furniture: NodeItem = { self_ref: '#/furniture' };
    expect(isDocling.GroupItem(furniture)).toBe(true);
  });

  it('identifies group by self_ref prefix', () => {
    const group: NodeItem = { self_ref: '#/groups/0' };
    expect(isDocling.GroupItem(group)).toBe(true);
  });

  it('identifies ListGroup, OrderedList, InlineGroup', () => {
    const lg: ListGroup = { self_ref: '#/groups/0', label: 'list' };
    const ol: OrderedList = { self_ref: '#/groups/1', label: 'ordered_list' };
    const ig: InlineGroup = { self_ref: '#/groups/2', label: 'inline' };
    expect(isDocling.ListGroup(lg)).toBe(true);
    expect(isDocling.ListGroup(ol)).toBe(false);
    expect(isDocling.OrderedList(ol)).toBe(true);
    expect(isDocling.InlineGroup(ig)).toBe(true);
  });

  it('rejects non-group nodes', () => {
    expect(isDocling.GroupItem({ self_ref: '#/texts/0' })).toBe(false);
    expect(isDocling.GroupItem({ self_ref: '#/tables/0' })).toBe(false);
    expect(isDocling.GroupItem({ self_ref: '#/pictures/0' })).toBe(false);
  });
});

describe('isDocling.DocItem', () => {
  it('accepts non-group node items', () => {
    expect(isDocling.DocItem({ self_ref: '#/texts/0', label: 'text' })).toBe(
      true
    );
    expect(isDocling.DocItem({ self_ref: '#/tables/0', label: 'table' })).toBe(
      true
    );
  });

  it('rejects group items', () => {
    expect(isDocling.DocItem({ self_ref: '#/body' })).toBe(false);
    expect(isDocling.DocItem({ self_ref: '#/groups/2' })).toBe(false);
  });

  it('rejects non-NodeItems', () => {
    expect(isDocling.DocItem({ label: 'text' })).toBe(false);
  });
});

describe('isDocling.Document', () => {
  it('identifies a DoclingDocument by schema_name', () => {
    const doc: DoclingDocument = {
      schema_name: 'DoclingDocument',
      version: '1.0.0',
      name: 'Test',
    };
    expect(isDocling.Document(doc)).toBe(true);
  });

  it('rejects objects without schema_name', () => {
    expect(isDocling.Document({ name: 'Test' })).toBe(false);
    expect(isDocling.Document({ schema_name: 'Other' })).toBe(false);
  });
});

